insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('dollar-cost-averaging', 1, '{"prices-fall":0,"no-guessing":true,"timing":0,"dca-math":0,"routine":[0,1,2,3]}'::jsonb, 6, 5, 'b92c1b28196fa99138915293eaea9a23ce74d98baba56ad263924b4b3d5d3141')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('dollar-cost-averaging', 1, 'en', 'Investing Regularly (DCA)', 'Stop trying to time the market', '[{"id":"intro","type":"info","title":"Same amount, every month","body":"Dollar-cost averaging (DCA) means investing a fixed amount at regular intervals, for example €100 every month, whatever the price. You automatically buy more shares when prices are low and fewer when they are high."},{"id":"prices-fall","type":"multiple_choice","prompt":"With DCA, when prices fall, your fixed monthly amount buys…","explanation":"€100 ÷ a lower price = more shares.","options":["More shares","Fewer shares","The same number of shares","No shares"]},{"id":"no-guessing","type":"true_false","statement":"DCA removes the need to guess the best moment to invest.","explanation":"It turns investing into a habit instead of a prediction."},{"id":"timing","type":"fill_blank","sentence":"Trying to buy at the lowest point and sell at the highest is called ___ the market.","explanation":"Even professionals rarely get market timing right consistently.","options":["timing","diversifying","indexing"]},{"id":"dca-math","type":"multiple_choice","prompt":"You invest €100 when a share costs €10, and €100 when it costs €5. How many shares do you own?","explanation":"10 shares + 20 shares = 30, at an average cost of about €6.67 per share.","options":["30","20","15","25"]},{"id":"routine","type":"order","prompt":"Order a simple long-term investing routine:","explanation":"Consistency beats intensity in long-term investing.","items":["Set a monthly amount you can afford","Invest it automatically on a fixed date","Keep investing in good and bad months","Review your plan once or twice a year"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('dollar-cost-averaging', 1, 'pt', 'Investir com Regularidade (DCA)', 'Deixa de tentar adivinhar o mercado', '[{"id":"intro","type":"info","title":"O mesmo valor, todos os meses","body":"O investimento periódico (DCA, dollar-cost averaging) consiste em investir um valor fixo em intervalos regulares, por exemplo 100 € por mês, seja qual for o preço. Compras automaticamente mais unidades quando os preços estão baixos e menos quando estão altos."},{"id":"prices-fall","type":"multiple_choice","prompt":"Com DCA, quando os preços descem, o teu valor mensal fixo compra…","explanation":"100 € ÷ um preço mais baixo = mais unidades.","options":["Mais unidades","Menos unidades","O mesmo número de unidades","Nenhuma unidade"]},{"id":"no-guessing","type":"true_false","statement":"O DCA elimina a necessidade de adivinhar o melhor momento para investir.","explanation":"Transforma o investimento num hábito em vez de uma previsão."},{"id":"timing","type":"fill_blank","sentence":"Tentar comprar no ponto mais baixo e vender no mais alto chama-se fazer ___ de mercado.","explanation":"Mesmo os profissionais raramente acertam no timing de mercado de forma consistente.","options":["timing","diversificação","indexação"]},{"id":"dca-math","type":"multiple_choice","prompt":"Investes 100 € quando uma ação custa 10 € e 100 € quando custa 5 €. Quantas ações tens?","explanation":"10 ações + 20 ações = 30, a um custo médio de cerca de 6,67 € por ação.","options":["30","20","15","25"]},{"id":"routine","type":"order","prompt":"Ordena uma rotina simples de investimento a longo prazo:","explanation":"No longo prazo, a consistência vale mais do que a intensidade.","items":["Definir um valor mensal que consegues pagar","Investi-lo automaticamente numa data fixa","Continuar a investir nos meses bons e maus","Rever o plano uma ou duas vezes por ano"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'dollar-cost-averaging';
