insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('etfs-and-index-funds', 1, 'en', 'ETFs and Index Funds', 'Own the whole market in one click', '[{"id":"intro","type":"info","title":"Buy the haystack","body":"An index, like the S&P 500 or the MSCI World, follows a group of companies. An index fund or ETF copies that index, giving you instant diversification, usually at a very low cost."},{"id":"sp500","type":"multiple_choice","prompt":"What does an S&P 500 index fund try to do?","explanation":"Index funds don''t try to beat the market; they aim to be the market.","options":["Match the performance of about 500 large US companies","Pick the 5 best stocks of the year","Guarantee a 5% return","Invest only in bonds"]},{"id":"active-vs-passive","type":"true_false","statement":"Over long periods, most actively managed funds fail to beat their benchmark index after fees.","explanation":"Studies such as S&P''s SPIVA reports consistently show this over 10+ year periods."},{"id":"etf-name","type":"fill_blank","sentence":"ETF stands for Exchange-Traded ___.","explanation":"ETFs are funds that trade on an exchange just like a share.","options":["Fund","Fee","Future"]},{"id":"advantage","type":"multiple_choice","prompt":"A main advantage of index ETFs is…","explanation":"They still carry market risk: when the market falls, the ETF falls too.","options":["Low costs and broad diversification","Guaranteed profits","No risk at all","Their prices only go up"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('etfs-and-index-funds', 1, 'pt', 'ETFs e Fundos de Índice', 'Investe no mercado inteiro com um clique', '[{"id":"intro","type":"info","title":"Compra o palheiro inteiro","body":"Um índice, como o S&P 500 ou o MSCI World, acompanha um grupo de empresas. Um fundo de índice ou ETF replica esse índice, dando-te diversificação imediata, normalmente com um custo muito baixo."},{"id":"sp500","type":"multiple_choice","prompt":"O que tenta fazer um fundo de índice do S&P 500?","explanation":"Os fundos de índice não tentam bater o mercado; tentam ser o mercado.","options":["Acompanhar o desempenho de cerca de 500 grandes empresas dos EUA","Escolher as 5 melhores ações do ano","Garantir um retorno de 5%","Investir apenas em obrigações"]},{"id":"active-vs-passive","type":"true_false","statement":"Em períodos longos, a maioria dos fundos de gestão ativa não consegue bater o seu índice de referência depois de custos.","explanation":"Estudos como os relatórios SPIVA da S&P mostram isto de forma consistente em períodos de mais de 10 anos."},{"id":"etf-name","type":"fill_blank","sentence":"ETF significa Exchange-Traded ___ (fundo negociado em bolsa).","explanation":"Os ETFs são fundos negociados em bolsa tal como uma ação.","options":["Fund","Fee","Future"]},{"id":"advantage","type":"multiple_choice","prompt":"Uma das principais vantagens dos ETFs de índice é…","explanation":"Continuam a ter risco de mercado: quando o mercado cai, o ETF também cai.","options":["Custos baixos e diversificação ampla","Lucros garantidos","Nenhum risco","Os preços só sobem"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'etfs-and-index-funds';
