    raise exception 'Lesson % v% changed without a version bump', 'fees-matter', 1;
  end if;
end $$;
insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('fees-matter', 1, '{"ter":0,"fee-gap":true,"fee-impact":0,"costs-to-check":0}'::jsonb, 5, 4, '1c20ac52dfc652c4e97de3720c494170920663325d91651ddbe6243f78481eb8')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('fees-matter', 1, 'en', 'Why Fees Matter', 'Small percentages, big differences', '[{"id":"intro","type":"info","title":"Fees compound too","body":"Fees look tiny, but they are charged every year on your whole balance, so they compound against you. Paying 2% a year instead of 0.2% can eat a large share of your returns over decades."},{"id":"ter","type":"multiple_choice","prompt":"What is a fund''s TER (Total Expense Ratio)?","explanation":"A TER of 0.2% costs €2 per year for every €1,000 invested.","options":["Its yearly cost as a % of your investment","The tax on your gains","The price of one share","The minimum investment"]},{"id":"fee-gap","type":"true_false","statement":"A fund charging 2% a year must beat a fund charging 0.2% by 1.8 percentage points every year just to match it.","explanation":"Fees are subtracted from returns, so higher fees set a higher bar every single year."},{"id":"fee-impact","type":"fill_blank","sentence":"Over 30 years, a 2% yearly fee instead of 0.2% can reduce your final amount by ___.","explanation":"Example: 7% vs 5.2% net per year over 30 years ends about 40% lower.","options":["more than a third","exactly zero","less than 1%"]},{"id":"costs-to-check","type":"multiple_choice","prompt":"Which costs should you check before investing?","explanation":"Costs are one of the few things investors can actually control.","options":["Fund fees, trading commissions and taxes","Only the fund''s logo","Only last year''s return","None, costs don''t matter"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('fees-matter', 1, 'pt', 'Porque é que os Custos Importam', 'Percentagens pequenas, diferenças grandes', '[{"id":"intro","type":"info","title":"Os custos também se acumulam","body":"Os custos parecem pequenos, mas são cobrados todos os anos sobre o valor total, por isso acumulam-se contra ti. Pagar 2% ao ano em vez de 0,2% pode comer uma grande parte dos teus ganhos ao longo de décadas."},{"id":"ter","type":"multiple_choice","prompt":"O que é a TER (Total Expense Ratio) de um fundo?","explanation":"Uma TER de 0,2% custa 2 € por ano por cada 1000 € investidos.","options":["O custo anual em % do teu investimento","O imposto sobre as mais-valias","O preço de uma unidade","O investimento mínimo"]},{"id":"fee-gap","type":"true_false","statement":"Um fundo que cobra 2% ao ano tem de render mais 1,8 pontos percentuais por ano do que um que cobra 0,2% só para o igualar.","explanation":"Os custos são subtraídos aos retornos, por isso custos mais altos exigem mais todos os anos."},{"id":"fee-impact","type":"fill_blank","sentence":"Em 30 anos, um custo de 2% ao ano em vez de 0,2% pode reduzir o valor final em ___.","explanation":"Exemplo: 7% vs 5,2% líquidos por ano durante 30 anos termina cerca de 40% abaixo.","options":["mais de um terço","exatamente zero","menos de 1%"]},{"id":"costs-to-check","type":"multiple_choice","prompt":"Que custos deves verificar antes de investir?","explanation":"Os custos são uma das poucas coisas que um investidor consegue realmente controlar.","options":["Custos do fundo, comissões de negociação e impostos","Apenas o logótipo do fundo","Apenas o retorno do ano passado","Nenhum, os custos não importam"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'fees-matter';
