insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('budget-50-30-20', 1, '{"savings":240,"buckets":[0,1,2],"needs-cap":0,"gross":false,"adapt":0}'::jsonb, 6, 5, 'f47775c19b2bae228d8083e8c03af72d3860faf8b8aac38dbd067926046c96b5')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('budget-50-30-20', 1, 'en', 'The 50/30/20 Rule', 'A simple starting point for your budget', '[{"id":"intro","type":"info","title":"Three buckets","body":"The 50/30/20 rule is a starting point: 50% of your net income for needs (housing, food, transport), 30% for wants (leisure, eating out) and 20% for savings or paying off debt. It is not a law: adapt it to your reality."},{"id":"savings","type":"numeric","prompt":"You take home €1,200 a month. Under the 50/30/20 rule, how much goes to savings (in €)?","explanation":"20% of €1,200 = €240.","unit":"€","decimals":0},{"id":"buckets","type":"match","prompt":"Match each part of the budget to an example","explanation":"Each euro gets a job before the month starts.","left":["Needs","Wants","Savings"],"right":["Rent, food and transport","Dinners out and subscriptions","Emergency fund and investing"]},{"id":"needs-cap","type":"multiple_choice","prompt":"With €1,500 net, what is the most the rule suggests for needs?","explanation":"50% of €1,500 = €750.","options":["€750","€450","€300","€1,500"]},{"id":"gross","type":"true_false","statement":"The 50/30/20 rule is applied to your gross salary.","explanation":"It applies to net income: what actually reaches your account after taxes and contributions."},{"id":"adapt","type":"fill_blank","sentence":"If rent takes more than half of your income, you can cut the ___ part to keep saving.","explanation":"Wants are the most flexible part of a budget.","options":["wants","taxes","interest"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('budget-50-30-20', 1, 'pt', 'A Regra 50/30/20', 'Um ponto de partida simples para o teu orçamento', '[{"id":"intro","type":"info","title":"Três partes","body":"A regra 50/30/20 é um ponto de partida: 50% do rendimento líquido para necessidades (casa, comida, transportes), 30% para desejos (lazer, jantares fora) e 20% para poupança ou para pagar dívidas. Não é uma lei: adapta-a à tua realidade."},{"id":"savings","type":"numeric","prompt":"Recebes 1200 € líquidos por mês. Segundo a regra 50/30/20, quanto vai para poupança (em €)?","explanation":"20% de 1200 € = 240 €.","unit":"€","decimals":0},{"id":"buckets","type":"match","prompt":"Liga cada parte do orçamento a um exemplo","explanation":"Cada euro tem uma função antes de o mês começar.","left":["Necessidades","Desejos","Poupança"],"right":["Renda, comida e transportes","Jantares fora e subscrições","Fundo de emergência e investimento"]},{"id":"needs-cap","type":"multiple_choice","prompt":"Com 1500 € líquidos, qual é o máximo que a regra sugere para necessidades?","explanation":"50% de 1500 € = 750 €.","options":["750 €","450 €","300 €","1500 €"]},{"id":"gross","type":"true_false","statement":"A regra 50/30/20 aplica-se ao salário bruto.","explanation":"Aplica-se ao rendimento líquido: o que chega efetivamente à conta depois de impostos e descontos."},{"id":"adapt","type":"fill_blank","sentence":"Se a renda ocupa mais de metade do rendimento, podes reduzir a parte dos ___ para continuar a poupar.","explanation":"Os desejos são a parte mais flexível de um orçamento.","options":["desejos","impostos","juros"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'budget-50-30-20';
