    raise exception 'Lesson % v% changed without a version bump', 'compound-interest', 1;
  end if;
end $$;
insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('compound-interest', 1, '{"simple-calc":0,"compound-calc":0,"time-matters":true,"rule-of-72":0,"growth-order":[0,1,2,3]}'::jsonb, 6, 5, '19fdfe54b66900ef8c0a316d31f34c43ddbcb9e7c9dfd53744be99f4a2e13f11')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('compound-interest', 1, 'en', 'The Magic of Compound Interest', 'Why your interest can earn interest', '[{"id":"intro","type":"info","title":"Simple vs. compound","body":"Simple interest is calculated only on the amount you started with. Compound interest is calculated on that amount plus the interest already earned, so your interest starts earning interest too. Over many years, this snowball effect becomes huge."},{"id":"simple-calc","type":"multiple_choice","prompt":"You deposit €100 at 10% simple interest per year. How much interest do you earn in 2 years?","explanation":"€10 each year, always calculated on the original €100.","options":["€20","€21","€10","€200"]},{"id":"compound-calc","type":"multiple_choice","prompt":"You invest €100 at 10% compound interest per year. How much do you have after 2 years?","explanation":"Year 1: €100 → €110. Year 2: €110 × 1.10 = €121. The extra €1 is interest on interest.","options":["€121","€120","€110","€200"]},{"id":"time-matters","type":"true_false","statement":"With compound interest, time is one of the biggest factors in how much your money grows.","explanation":"The longer the snowball rolls, the bigger it gets. Starting early is a superpower."},{"id":"rule-of-72","type":"fill_blank","sentence":"The Rule of 72 says that at an 8% yearly return, money roughly doubles in about ___ years.","explanation":"72 ÷ 8 = 9 years.","options":["9","72","4"]},{"id":"growth-order","type":"order","prompt":"Starting with €1,000, order from the least to the most money after 20 years:","explanation":"€1,000 → €1,400 → about €1,486 → about €3,207.","items":["Kept in a drawer","2% simple interest","2% compound interest","6% compound interest"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('compound-interest', 1, 'pt', 'A Magia dos Juros Compostos', 'Porque é que os teus juros podem render juros', '[{"id":"intro","type":"info","title":"Simples vs. compostos","body":"Os juros simples são calculados apenas sobre o valor inicial. Os juros compostos são calculados sobre esse valor mais os juros já ganhos, por isso os teus juros também começam a render. Ao longo de muitos anos, este efeito bola de neve torna-se enorme."},{"id":"simple-calc","type":"multiple_choice","prompt":"Depositas 100 € a 10% de juro simples por ano. Quanto ganhas de juros em 2 anos?","explanation":"10 € por ano, sempre calculados sobre os 100 € iniciais.","options":["20 €","21 €","10 €","200 €"]},{"id":"compound-calc","type":"multiple_choice","prompt":"Investes 100 € a 10% de juro composto por ano. Quanto tens ao fim de 2 anos?","explanation":"Ano 1: 100 € → 110 €. Ano 2: 110 € × 1,10 = 121 €. O euro extra são juros sobre juros.","options":["121 €","120 €","110 €","200 €"]},{"id":"time-matters","type":"true_false","statement":"Com juros compostos, o tempo é um dos fatores que mais influencia o crescimento do teu dinheiro.","explanation":"Quanto mais tempo a bola de neve rola, maior fica. Começar cedo é um superpoder."},{"id":"rule-of-72","type":"fill_blank","sentence":"A Regra dos 72 diz que, com uma rentabilidade de 8% ao ano, o dinheiro duplica em cerca de ___ anos.","explanation":"72 ÷ 8 = 9 anos.","options":["9","72","4"]},{"id":"growth-order","type":"order","prompt":"Começando com 1000 €, ordena do menor para o maior valor ao fim de 20 anos:","explanation":"1000 € → 1400 € → cerca de 1486 € → cerca de 3207 €.","items":["Guardado numa gaveta","2% de juro simples","2% de juro composto","6% de juro composto"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'compound-interest';
