insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('debit-vs-credit-cards', 1, '{"debit":0,"minimum":false,"terms":[0,1,2,3],"full-payment":0,"safest":0}'::jsonb, 6, 5, '0790f450cd2930c8cd159a628866d2b2d7b8c074c1cd0d096c8769c3eef781cd')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('debit-vs-credit-cards', 1, 'en', 'Debit vs Credit Cards', 'Your money or borrowed money?', '[{"id":"intro","type":"info","title":"Two very different cards","body":"With a debit card you pay with money you already have in your account. With a credit card you use money lent by the bank, which you must pay back; if you don''t pay the full amount by the due date, you pay interest, usually high."},{"id":"debit","type":"multiple_choice","prompt":"With a debit card, the money comes…","explanation":"Debit spends what you have; it cannot create debt by itself.","options":["from your account, at the time of purchase","from a bank loan","from next month''s salary","from a friend''s card"]},{"id":"minimum","type":"true_false","statement":"Paying only the minimum on a credit card avoids interest.","explanation":"Interest is charged on the part you do not pay, so the debt keeps growing."},{"id":"terms","type":"match","prompt":"Match each term to its meaning","explanation":"Read the APR (TAEG in Portugal) before using credit: it includes interest and fees.","left":["Debit","Credit","Minimum payment","APR (TAEG)"],"right":["Uses your own money","Uses borrowed money","Smallest amount you can pay each month","Total yearly cost of the credit"]},{"id":"full-payment","type":"numeric","prompt":"You spend €300 on a credit card and pay the full amount by the due date. How much interest do you usually pay on those purchases (in €)?","explanation":"Paying the full balance on time normally avoids interest on purchases. Check your card terms.","unit":"€","decimals":0},{"id":"safest","type":"fill_blank","sentence":"If you use a credit card, the safest habit is to pay ___ every month.","explanation":"That way the card is a payment tool, not a loan.","options":["the full balance","only the minimum","nothing"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('debit-vs-credit-cards', 1, 'pt', 'Cartão de Débito vs Crédito', 'O teu dinheiro ou dinheiro emprestado?', '[{"id":"intro","type":"info","title":"Dois cartões muito diferentes","body":"Com o cartão de débito pagas com dinheiro que já tens na conta. Com o cartão de crédito usas dinheiro emprestado pelo banco, que tens de devolver; se não pagares o total até à data-limite, pagas juros, normalmente altos."},{"id":"debit","type":"multiple_choice","prompt":"Com um cartão de débito, o dinheiro sai…","explanation":"O débito gasta o que tens; por si só não cria dívida.","options":["da tua conta, no momento da compra","de um empréstimo do banco","do salário do próximo mês","do cartão de um amigo"]},{"id":"minimum","type":"true_false","statement":"Pagar só o valor mínimo do cartão de crédito evita pagar juros.","explanation":"Os juros são cobrados sobre a parte que não pagas, por isso a dívida continua a crescer."},{"id":"terms","type":"match","prompt":"Liga cada termo ao seu significado","explanation":"Lê a TAEG antes de usar crédito: inclui juros e encargos.","left":["Débito","Crédito","Pagamento mínimo","TAEG"],"right":["Usa o teu próprio dinheiro","Usa dinheiro emprestado","O valor mais pequeno que podes pagar por mês","Custo total anual do crédito"]},{"id":"full-payment","type":"numeric","prompt":"Gastas 300 € no cartão de crédito e pagas o valor total até à data-limite. Quanto pagas normalmente de juros por essas compras (em €)?","explanation":"Pagar o total a tempo normalmente evita juros sobre as compras. Confirma as condições do teu cartão.","unit":"€","decimals":0},{"id":"safest","type":"fill_blank","sentence":"Se usares cartão de crédito, o hábito mais seguro é pagar ___ todos os meses.","explanation":"Assim o cartão é um meio de pagamento, não um empréstimo.","options":["o valor total","só o mínimo","nada"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'debit-vs-credit-cards';
