insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('emergency-fund', 1, '{"where-to-keep":0,"not-in-stocks":false,"months-rule":0,"target":0,"priorities":[0,1,2,3]}'::jsonb, 6, 5, '83855c4764a421c0bc3d920d8407ce87ef86a2a6a65adedf86f2861ff383407b')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('emergency-fund', 1, 'en', 'Your Emergency Fund', 'The safety net every investor needs first', '[{"id":"intro","type":"info","title":"Expect the unexpected","body":"An emergency fund is money set aside for surprises: a broken car, a medical bill or losing your job. A common guideline is to keep 3 to 6 months of essential expenses somewhere safe and easy to access."},{"id":"where-to-keep","type":"multiple_choice","prompt":"Where is the best place to keep an emergency fund?","explanation":"Emergency money must be safe and available the day you need it.","options":["A savings account you can access quickly","Shares of a single company","A 10-year term deposit","Lent to a friend"]},{"id":"not-in-stocks","type":"true_false","statement":"Your emergency fund should be invested in the stock market so it grows faster.","explanation":"Stock prices can fall exactly when you need the money, for example during a recession when jobs are also at risk."},{"id":"months-rule","type":"fill_blank","sentence":"A common guideline is to keep ___ months of essential expenses in an emergency fund.","explanation":"Enough to cover a few months without income, without leaving too much money idle.","options":["3 to 6","0","24 to 36"]},{"id":"target","type":"multiple_choice","prompt":"Your essential expenses are €1,000 per month. What is a reasonable emergency fund target?","explanation":"3 to 6 months × €1,000. Credit cards charge high interest and are not a safety net.","options":["€3,000 to €6,000","€100","€50,000","€0, a credit card is enough"]},{"id":"priorities","type":"order","prompt":"Order a common sequence of money priorities for beginners:","explanation":"High-interest debt often costs more than investments earn, so it usually comes before investing.","items":["Pay for essentials (rent, food, bills)","Build a small emergency fund","Pay off high-interest debt","Start investing for the long term"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('emergency-fund', 1, 'pt', 'O Teu Fundo de Emergência', 'A rede de segurança que todo o investidor precisa primeiro', '[{"id":"intro","type":"info","title":"Conta com o inesperado","body":"Um fundo de emergência é dinheiro reservado para imprevistos: um carro avariado, uma despesa médica ou perder o emprego. Uma regra comum é guardar 3 a 6 meses de despesas essenciais num sítio seguro e de fácil acesso."},{"id":"where-to-keep","type":"multiple_choice","prompt":"Qual é o melhor sítio para guardar um fundo de emergência?","explanation":"O dinheiro de emergência tem de estar seguro e disponível no dia em que precisares dele.","options":["Uma conta poupança com acesso rápido","Ações de uma única empresa","Um depósito a prazo de 10 anos","Emprestado a um amigo"]},{"id":"not-in-stocks","type":"true_false","statement":"O teu fundo de emergência deve ser investido em bolsa para crescer mais depressa.","explanation":"As ações podem cair precisamente quando precisas do dinheiro, por exemplo numa recessão, quando os empregos também estão em risco."},{"id":"months-rule","type":"fill_blank","sentence":"Uma regra comum é guardar ___ meses de despesas essenciais num fundo de emergência.","explanation":"O suficiente para cobrir alguns meses sem rendimento, sem deixar demasiado dinheiro parado.","options":["3 a 6","0","24 a 36"]},{"id":"target","type":"multiple_choice","prompt":"As tuas despesas essenciais são 1000 € por mês. Qual é um objetivo razoável para o fundo de emergência?","explanation":"3 a 6 meses × 1000 €. Os cartões de crédito cobram juros altos e não são uma rede de segurança.","options":["3000 € a 6000 €","100 €","50 000 €","0 €, um cartão de crédito chega"]},{"id":"priorities","type":"order","prompt":"Ordena uma sequência comum de prioridades financeiras para quem está a começar:","explanation":"As dívidas com juros altos custam muitas vezes mais do que os investimentos rendem, por isso normalmente vêm antes de investir.","items":["Pagar o essencial (renda, comida, contas)","Criar um pequeno fundo de emergência","Pagar dívidas com juros altos","Começar a investir a longo prazo"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'emergency-fund';
