insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('inflation', 1, '{"drawer":0,"basket":52,"ecb-target":false,"terms":[0,1,2,3],"beats-deposit":0}'::jsonb, 6, 5, 'ea32b386239adfc1652dd7d4bb4483fa6733b005b1a720f4adcc36e2bae79931')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('inflation', 1, 'en', 'Inflation', 'Why money left idle loses value', '[{"id":"intro","type":"info","title":"Prices go up","body":"Inflation is the general rise in prices. If prices go up 3% in a year, €100 buys less than before: idle money loses purchasing power. The European Central Bank (ECB) aims to keep euro area inflation at 2% over the medium term."},{"id":"drawer","type":"multiple_choice","prompt":"With 3% yearly inflation, what happens to €100 kept in a drawer?","explanation":"The note still says €100, but prices are higher, so it buys less.","options":["It buys fewer things a year later","It becomes €103","It keeps exactly the same purchasing power","It disappears"]},{"id":"basket","type":"numeric","prompt":"A basket of groceries costs €50 and prices rise 4% in a year. How much does it cost next year (in €)?","explanation":"€50 × 1.04 = €52.","unit":"€","decimals":0},{"id":"ecb-target","type":"true_false","statement":"The ECB aims for 0% inflation.","explanation":"The target is 2% over the medium term: low and stable inflation, not zero."},{"id":"terms","type":"match","prompt":"Match each term to its meaning","explanation":"These four words appear in almost every news story about prices.","left":["Inflation","Deflation","Purchasing power","ECB"],"right":["General rise in prices","General fall in prices","What your money can buy","Central bank of the euro area"]},{"id":"beats-deposit","type":"fill_blank","sentence":"When inflation is higher than the interest on your deposit, your money loses ___.","explanation":"The balance may even grow in euros, but it buys less.","options":["purchasing power","its guarantee","its account number"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('inflation', 1, 'pt', 'Inflação', 'Porque é que o dinheiro parado perde valor', '[{"id":"intro","type":"info","title":"Os preços sobem","body":"A inflação é a subida generalizada dos preços. Se os preços sobem 3% num ano, 100 € compram menos do que antes: o dinheiro parado perde poder de compra. O Banco Central Europeu (BCE) procura manter a inflação da zona euro nos 2% a médio prazo."},{"id":"drawer","type":"multiple_choice","prompt":"Com uma inflação de 3% ao ano, o que acontece a 100 € guardados numa gaveta?","explanation":"A nota continua a dizer 100 €, mas os preços estão mais altos, por isso compra menos.","options":["Compram menos coisas daqui a um ano","Passam a valer 103 €","Mantêm exatamente o mesmo poder de compra","Desaparecem"]},{"id":"basket","type":"numeric","prompt":"Um cabaz de compras custa 50 € e os preços sobem 4% num ano. Quanto custa o cabaz no ano seguinte (em €)?","explanation":"50 € × 1,04 = 52 €.","unit":"€","decimals":0},{"id":"ecb-target","type":"true_false","statement":"O objetivo do BCE é ter uma inflação de 0%.","explanation":"O objetivo é 2% a médio prazo: inflação baixa e estável, não zero."},{"id":"terms","type":"match","prompt":"Liga cada termo ao seu significado","explanation":"Estas quatro palavras aparecem em quase todas as notícias sobre preços.","left":["Inflação","Deflação","Poder de compra","BCE"],"right":["Subida geral dos preços","Descida geral dos preços","O que consegues comprar com o teu dinheiro","Banco central da zona euro"]},{"id":"beats-deposit","type":"fill_blank","sentence":"Quando a inflação é mais alta do que o juro do teu depósito, o teu dinheiro perde ___.","explanation":"O saldo pode até subir em euros, mas compra menos.","options":["poder de compra","a garantia","o número de conta"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'inflation';
