insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('needs-vs-wants', 1, '{"which-need":0,"clothes":true,"impulse":0,"wait":0,"subscription":144}'::jsonb, 6, 5, '7f8a63eb16a39868455e3e2b2ef4864bdc79b3fcc059049c83faccb1d3ae8b5d')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('needs-vs-wants', 1, 'en', 'Needs vs Wants', 'Spend on purpose, not on impulse', '[{"id":"intro","type":"info","title":"Essential or nice to have?","body":"A need is essential to live and work (housing, basic food, transport). A want makes life better but you could do without it (a new phone, streaming). Many expenses mix both: you need to eat, but eating out is a want."},{"id":"which-need","type":"multiple_choice","prompt":"Which of these is a need?","explanation":"Getting to work is essential; the others are choices.","options":["A monthly transport pass to get to work","A third streaming subscription","A top-of-the-range new phone","Dinner out at the weekend"]},{"id":"clothes","type":"true_false","statement":"Buying clothes can be a need or a want, depending on what you buy.","explanation":"A winter coat when you have none is a need; the fifth pair of trainers is a want."},{"id":"impulse","type":"multiple_choice","prompt":"Impulse purchases happen most when you…","explanation":"Plans and lists protect you from impulses.","options":["shop in a hurry or emotional","make a list before going out","compare prices","set a budget"]},{"id":"wait","type":"fill_blank","sentence":"Before an impulse buy, a useful rule is to wait ___ before deciding.","explanation":"If you still want it a day later, it is probably a considered choice.","options":["24 hours","one year","zero seconds"]},{"id":"subscription","type":"numeric","prompt":"You cancel a €12-a-month subscription. How much do you save in a year (in €)?","explanation":"€12 × 12 = €144.","unit":"€","decimals":0}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('needs-vs-wants', 1, 'pt', 'Necessidades vs Desejos', 'Gasta com intenção, não por impulso', '[{"id":"intro","type":"info","title":"Essencial ou dispensável?","body":"Uma necessidade é essencial para viver e trabalhar (casa, comida básica, transporte). Um desejo melhora a vida, mas podes passar sem ele (telemóvel novo, streaming). Muitas despesas misturam as duas coisas: precisas de comer, mas jantar fora é um desejo."},{"id":"which-need","type":"multiple_choice","prompt":"Qual destas é uma necessidade?","explanation":"Ir trabalhar é essencial; as outras são escolhas.","options":["Passe mensal de transportes para ir trabalhar","Uma terceira subscrição de streaming","Um telemóvel novo topo de gama","Jantar fora ao fim de semana"]},{"id":"clothes","type":"true_false","statement":"Comprar roupa pode ser uma necessidade ou um desejo, dependendo do que compras.","explanation":"Um casaco de inverno quando não tens nenhum é uma necessidade; o quinto par de sapatilhas é um desejo."},{"id":"impulse","type":"multiple_choice","prompt":"As compras por impulso acontecem sobretudo quando…","explanation":"Planos e listas protegem-te dos impulsos.","options":["compras com pressa ou emocionado","fazes uma lista antes de sair","comparas preços","defines um orçamento"]},{"id":"wait","type":"fill_blank","sentence":"Antes de uma compra por impulso, uma regra útil é esperar ___ antes de decidir.","explanation":"Se ainda quiseres no dia seguinte, provavelmente é uma escolha pensada.","options":["24 horas","um ano","zero segundos"]},{"id":"subscription","type":"numeric","prompt":"Cancelas uma subscrição de 12 € por mês. Quanto poupas num ano (em €)?","explanation":"12 € × 12 = 144 €.","unit":"€","decimals":0}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'needs-vs-wants';
