insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('pay-yourself-first', 1, '{"meaning":0,"leftovers":true,"left-to-spend":900,"payday":[0,1,2,3],"automatic":0}'::jsonb, 6, 5, '3fae208b7ec9cb92585ee953362aac7763e5cd5de95a84d40efe56a88f9474fc')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('pay-yourself-first', 1, 'en', 'Pay Yourself First', 'Save on payday, not with what is left', '[{"id":"intro","type":"info","title":"Savings come first","body":"Paying yourself first means setting your savings aside on the day you get paid, and only then spending the rest. An automatic transfer to another account does it for you, without relying on willpower."},{"id":"meaning","type":"multiple_choice","prompt":"What does \"pay yourself first\" mean?","explanation":"Savings become a fixed \"expense\" of the month.","options":["Save as soon as you get paid, before spending","Buy what you want first","Pay other people''s debts","Spend everything and save what is left"]},{"id":"leftovers","type":"true_false","statement":"Saving only what is left at the end of the month usually means saving less.","explanation":"Spending tends to grow to fill whatever money is available."},{"id":"left-to-spend","type":"numeric","prompt":"You earn €1,000 and an automatic transfer moves 10% to savings on payday. How much is left to spend (in €)?","explanation":"€1,000 − 10% = €900.","unit":"€","decimals":0},{"id":"payday","type":"order","prompt":"Order what happens on payday:","explanation":"Saving before spending is the whole trick.","items":["Your salary arrives","The automatic transfer moves your savings","Fixed bills are paid","You use the rest day to day"]},{"id":"automatic","type":"fill_blank","sentence":"An ___ transfer to another account turns saving into a habit.","explanation":"Automation removes the daily decision.","options":["automatic","forgotten","yearly"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('pay-yourself-first', 1, 'pt', 'Paga-te Primeiro a Ti', 'Poupa no dia do salário, não com o que sobra', '[{"id":"intro","type":"info","title":"A poupança vem primeiro","body":"Pagar-te primeiro significa pôr de lado a poupança no próprio dia em que recebes, e só depois gastar o resto. Uma transferência automática para outra conta faz isto por ti, sem depender da força de vontade."},{"id":"meaning","type":"multiple_choice","prompt":"O que significa \"pagar-te primeiro\"?","explanation":"A poupança passa a ser uma \"despesa\" fixa do mês.","options":["Poupar assim que recebes, antes de gastar","Comprar primeiro o que te apetece","Pagar as dívidas dos outros","Gastar tudo e poupar o que sobrar"]},{"id":"leftovers","type":"true_false","statement":"Poupar só o que sobra no fim do mês costuma resultar em poupar menos.","explanation":"Os gastos tendem a crescer até ocupar o dinheiro disponível."},{"id":"left-to-spend","type":"numeric","prompt":"Recebes 1000 € e uma transferência automática de 10% vai para a poupança no dia do salário. Quanto fica para gastar (em €)?","explanation":"1000 € − 10% = 900 €.","unit":"€","decimals":0},{"id":"payday","type":"order","prompt":"Ordena o que acontece no dia do salário:","explanation":"Poupar antes de gastar é todo o segredo.","items":["O salário entra na conta","A transferência automática envia a poupança","Pagas as contas fixas","Usas o restante no dia a dia"]},{"id":"automatic","type":"fill_blank","sentence":"Uma transferência ___ para outra conta transforma a poupança num hábito.","explanation":"Automatizar elimina a decisão de todos os dias.","options":["automática","esquecida","anual"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'pay-yourself-first';
