insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('phishing', 1, '{"bank-asks-code":false,"blocked-sms":0,"types":[0,1,2,3],"urgency":0,"if-it-happens":[0,1,2,3]}'::jsonb, 6, 5, 'eba34dcaff914a2097e3a4e7d1002e442a72e35c93b6415072cf62819b2e8b95')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('phishing', 1, 'en', 'Phishing and Fake Messages', 'Spot scams before they cost you', '[{"id":"intro","type":"info","title":"Someone pretending to be your bank","body":"Phishing is a scam where someone pretends to be your bank, a delivery company or the tax office to make you click a link or give away your data. Banks never ask for your authentication codes by SMS, email or phone."},{"id":"bank-asks-code","type":"true_false","statement":"Your bank may ask you by SMS for the code you received to confirm an operation.","explanation":"Codes are only for you to type yourself in the official app or website. Anyone asking for them is a scammer."},{"id":"blocked-sms","type":"multiple_choice","prompt":"You get an SMS: \"Your account has been blocked, click here\". What should you do?","explanation":"Use the number on your card or the official app, never the link in the message.","options":["Don''t click and contact the bank through its official channels","Click quickly to unblock it","Reply with your details","Forward it to friends"]},{"id":"types","type":"match","prompt":"Match each term to its meaning","explanation":"The channel changes, the goal is the same: your data and your money.","left":["Phishing","Smishing","Vishing","Strong authentication"],"right":["Scam by fake email or website","Phishing by SMS","Scam by phone call","Confirming with two different factors"]},{"id":"urgency","type":"fill_blank","sentence":"A message that creates ___ (\"reply within 1 hour!\") is a typical sign of a scam.","explanation":"Scammers rush you so you do not stop to think.","options":["urgency","calm","trust"]},{"id":"if-it-happens","type":"order","prompt":"You gave your details by mistake. Order what to do:","explanation":"Speed matters: the sooner the bank knows, the more it can do.","items":["Call your bank''s official line straight away","Block cards and change passwords","Check your account movements","Report it to the authorities"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('phishing', 1, 'pt', 'Phishing e Mensagens Falsas', 'Identifica burlas antes que te custem caro', '[{"id":"intro","type":"info","title":"Alguém a fingir ser o teu banco","body":"Phishing é uma burla em que alguém se faz passar pelo teu banco, pelos CTT ou pelas Finanças para te levar a clicar num link ou a dar os teus dados. Os bancos nunca pedem códigos de autenticação por SMS, email ou telefone."},{"id":"bank-asks-code","type":"true_false","statement":"O teu banco pode pedir-te por SMS o código que recebeste para confirmar uma operação.","explanation":"Os códigos são só para escreveres tu na app ou no site oficial. Quem os pede é um burlão."},{"id":"blocked-sms","type":"multiple_choice","prompt":"Recebes um SMS: \"A sua conta foi bloqueada, clique aqui\". O que deves fazer?","explanation":"Usa o número do teu cartão ou a app oficial, nunca o link da mensagem.","options":["Não clicar e contactar o banco pelos canais oficiais","Clicar rapidamente para desbloquear","Responder com os teus dados","Reencaminhar para os amigos"]},{"id":"types","type":"match","prompt":"Liga cada termo ao seu significado","explanation":"O canal muda, o objetivo é o mesmo: os teus dados e o teu dinheiro.","left":["Phishing","Smishing","Vishing","Autenticação forte"],"right":["Burla por email ou site falso","Phishing por SMS","Burla por chamada telefónica","Confirmação com dois fatores diferentes"]},{"id":"urgency","type":"fill_blank","sentence":"Uma mensagem que cria ___ (\"responda em 1 hora!\") é um sinal típico de burla.","explanation":"Os burlões apressam-te para não parares para pensar.","options":["urgência","calma","confiança"]},{"id":"if-it-happens","type":"order","prompt":"Deste os teus dados por engano. Ordena o que fazer:","explanation":"A rapidez conta: quanto mais cedo o banco souber, mais pode fazer.","items":["Contactar logo o banco pela linha oficial","Bloquear cartões e mudar palavras-passe","Verificar os movimentos da conta","Apresentar queixa às autoridades"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'phishing';
