    raise exception 'Lesson % v% changed without a version bump', 'real-interest-rate', 1;
  end if;
end $$;
insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('real-interest-rate', 1, '{"calc-real":1.5,"positive":0,"balance-falls":false,"terms":[0,1,2],"grow":0}'::jsonb, 6, 5, '43bb6b27a5a2540e0207a865638f274aad9a15f2c78fc67e4720b5844893c60f')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('real-interest-rate', 1, 'en', 'Real vs Nominal Returns', 'What you really earn after inflation', '[{"id":"intro","type":"info","title":"Subtract inflation","body":"The nominal return is the one you see advertised, for example 3% a year. The real return takes inflation into account: roughly, real ≈ nominal − inflation. If a deposit pays 2% and inflation is 3%, you lose about 1% of purchasing power."},{"id":"calc-real","type":"numeric","prompt":"A deposit pays 4% and inflation is 2.5%. What is the approximate real return (in %)?","explanation":"4% − 2.5% ≈ 1.5%.","unit":"%","decimals":1},{"id":"positive","type":"multiple_choice","prompt":"Which situation has a positive real return?","explanation":"Only when the return beats inflation does your purchasing power grow.","options":["5% interest with 2% inflation","1% interest with 3% inflation","2% interest with 2% inflation","0% interest with 1% inflation"]},{"id":"balance-falls","type":"true_false","statement":"If your account pays 1% and inflation is 4%, your balance goes down in euros.","explanation":"The balance in euros goes up by 1%; what falls (about 3%) is what it can buy."},{"id":"terms","type":"match","prompt":"Match each term to its meaning","explanation":"Always compare what you earn with how fast prices are rising.","left":["Nominal return","Real return","Inflation"],"right":["Advertised rate, before inflation","Rate after subtracting inflation","General rise in prices"]},{"id":"grow","type":"fill_blank","sentence":"For your purchasing power to grow, an investment has to earn ___ than inflation.","explanation":"Earning the same as inflation only keeps you where you are.","options":["more","less","the same"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('real-interest-rate', 1, 'pt', 'Rentabilidade Real vs Nominal', 'O que ganhas realmente depois da inflação', '[{"id":"intro","type":"info","title":"Desconta a inflação","body":"A rentabilidade nominal é a que vês anunciada, por exemplo 3% ao ano. A rentabilidade real tem em conta a inflação: de forma aproximada, real ≈ nominal − inflação. Se um depósito rende 2% e a inflação é 3%, perdes cerca de 1% de poder de compra."},{"id":"calc-real","type":"numeric","prompt":"Um depósito rende 4% e a inflação é 2,5%. Qual é, aproximadamente, a rentabilidade real (em %)?","explanation":"4% − 2,5% ≈ 1,5%.","unit":"%","decimals":1},{"id":"positive","type":"multiple_choice","prompt":"Qual destas situações tem rentabilidade real positiva?","explanation":"Só quando a rentabilidade supera a inflação é que o teu poder de compra cresce.","options":["Juro de 5% com inflação de 2%","Juro de 1% com inflação de 3%","Juro de 2% com inflação de 2%","Juro de 0% com inflação de 1%"]},{"id":"balance-falls","type":"true_false","statement":"Se a conta rende 1% e a inflação é 4%, o saldo diminui em euros.","explanation":"O saldo em euros sobe 1%; o que cai (cerca de 3%) é o que consegue comprar."},{"id":"terms","type":"match","prompt":"Liga cada termo ao seu significado","explanation":"Compara sempre o que ganhas com a velocidade a que os preços sobem.","left":["Rentabilidade nominal","Rentabilidade real","Inflação"],"right":["Taxa anunciada, antes da inflação","Taxa depois de descontar a inflação","Subida geral dos preços"]},{"id":"grow","type":"fill_blank","sentence":"Para o teu poder de compra crescer, o investimento precisa de render ___ do que a inflação.","explanation":"Render o mesmo que a inflação só te mantém onde estás.","options":["mais","menos","o mesmo"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'real-interest-rate';
