insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('saving-goals', 1, '{"monthly":150,"well-defined":0,"short-term":true,"horizon":[0,1,2,3],"milestones":0}'::jsonb, 6, 5, 'c5920402d325972cad75da16ddeb0fd19fe6ab1edb7083b7d1a2d44918faa23c')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('saving-goals', 1, 'en', 'Saving Goals', 'Turn wishes into monthly amounts', '[{"id":"intro","type":"info","title":"Amount + date","body":"A good saving goal has an amount and a date: \"save €1,200 for a trip in 12 months\". Divide the amount by the number of months and you know how much to save each month."},{"id":"monthly","type":"numeric","prompt":"You want to save €900 in 6 months. How much do you need to save per month (in €)?","explanation":"€900 ÷ 6 = €150.","unit":"€","decimals":0},{"id":"well-defined","type":"multiple_choice","prompt":"Which goal is best defined?","explanation":"It has an amount, a purpose and a deadline.","options":["Save €600 for a laptop by June","Save more","Be rich one day","Spend less sometimes"]},{"id":"short-term","type":"true_false","statement":"Short-term goals (under a year) should be kept somewhere safe and easy to access.","explanation":"If you need the money soon, you cannot risk it being worth less at that moment."},{"id":"horizon","type":"order","prompt":"Order these goals from shortest to longest term:","explanation":"The time horizon changes where the money should be kept.","items":["A birthday present in 2 months","A trip next summer","A deposit for a house","Retirement"]},{"id":"milestones","type":"fill_blank","sentence":"Breaking a big goal into ___ milestones helps you stay motivated.","explanation":"Small wins along the way keep you going.","options":["monthly","secret","impossible"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('saving-goals', 1, 'pt', 'Objetivos de Poupança', 'Transforma desejos em valores mensais', '[{"id":"intro","type":"info","title":"Valor + data","body":"Um bom objetivo de poupança tem um valor e uma data: \"juntar 1200 € para uma viagem daqui a 12 meses\". Dividindo o valor pelo número de meses ficas a saber quanto poupar por mês."},{"id":"monthly","type":"numeric","prompt":"Queres juntar 900 € em 6 meses. Quanto tens de poupar por mês (em €)?","explanation":"900 € ÷ 6 = 150 €.","unit":"€","decimals":0},{"id":"well-defined","type":"multiple_choice","prompt":"Qual destes objetivos está melhor definido?","explanation":"Tem um valor, um propósito e um prazo.","options":["Juntar 600 € para um portátil até junho","Poupar mais","Ser rico um dia","Gastar menos às vezes"]},{"id":"short-term","type":"true_false","statement":"Os objetivos de curto prazo (menos de 1 ano) devem estar num sítio seguro e de acesso fácil.","explanation":"Se precisas do dinheiro em breve, não podes arriscar que valha menos nessa altura."},{"id":"horizon","type":"order","prompt":"Ordena estes objetivos do prazo mais curto para o mais longo:","explanation":"O horizonte temporal muda o sítio onde o dinheiro deve estar.","items":["Prenda de anos daqui a 2 meses","Viagem no próximo verão","Entrada para uma casa","Reforma"]},{"id":"milestones","type":"fill_blank","sentence":"Dividir um objetivo grande em metas ___ ajuda a manter a motivação.","explanation":"Pequenas vitórias pelo caminho ajudam a continuar.","options":["mensais","secretas","impossíveis"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'saving-goals';
