insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('tracking-expenses', 1, '{"types":[0,1,2],"insurance":30,"start":0,"small":false,"steps":[0,1,2,3]}'::jsonb, 6, 5, '623b6c07bb2e69b9bc80261af8b408edccd4ff0a494c61dbcd69e1853e44ba99')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('tracking-expenses', 1, 'en', 'Tracking Expenses', 'Find out where your money really goes', '[{"id":"intro","type":"info","title":"Fixed, variable, occasional","body":"Fixed expenses repeat with the same amount (rent, gym). Variable expenses change every month (groceries, fuel). Occasional expenses appear a few times a year (car insurance, gifts). Tracking everything for one month shows where your money really goes."},{"id":"types","type":"match","prompt":"Match each type of expense to an example","explanation":"Knowing the type helps you plan: fixed ones are predictable, occasional ones catch people off guard.","left":["Fixed","Variable","Occasional"],"right":["Monthly rent","Groceries","Yearly car insurance"]},{"id":"insurance","type":"numeric","prompt":"Your car insurance costs €360 a year. How much should you set aside each month (in €)?","explanation":"€360 ÷ 12 = €30 a month.","unit":"€","decimals":0},{"id":"start","type":"multiple_choice","prompt":"What''s the best way to start controlling your spending?","explanation":"You cannot improve what you do not measure.","options":["Record every expense for a month","Cut all leisure at once","Only look at the balance at the end of the month","Get a credit card"]},{"id":"small","type":"true_false","statement":"Small daily expenses, like a €1 coffee, have no impact on a budget.","explanation":"€1 a day adds up to about €365 a year."},{"id":"steps","type":"order","prompt":"Order the steps to build a budget:","explanation":"Measure first, then decide.","items":["Record what you spend for a month","Group it into categories","Compare it with your income","Set limits for next month"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('tracking-expenses', 1, 'pt', 'Registar Despesas', 'Descobre para onde vai realmente o dinheiro', '[{"id":"intro","type":"info","title":"Fixas, variáveis, ocasionais","body":"As despesas fixas repetem-se com o mesmo valor (renda, ginásio). As variáveis mudam todos os meses (supermercado, combustível). As ocasionais aparecem poucas vezes por ano (seguro do carro, prendas). Registar tudo durante um mês mostra para onde vai realmente o dinheiro."},{"id":"types","type":"match","prompt":"Liga cada tipo de despesa a um exemplo","explanation":"Saber o tipo ajuda a planear: as fixas são previsíveis, as ocasionais apanham muita gente desprevenida.","left":["Fixa","Variável","Ocasional"],"right":["Renda da casa","Supermercado","Seguro anual do carro"]},{"id":"insurance","type":"numeric","prompt":"Pagas um seguro anual de 360 €. Quanto deves pôr de parte por mês para não seres apanhado de surpresa (em €)?","explanation":"360 € ÷ 12 = 30 € por mês.","unit":"€","decimals":0},{"id":"start","type":"multiple_choice","prompt":"Qual é a melhor forma de começar a controlar as despesas?","explanation":"Não consegues melhorar o que não medes.","options":["Registar todos os gastos durante um mês","Cortar todo o lazer de uma vez","Olhar só para o saldo no fim do mês","Pedir um cartão de crédito"]},{"id":"small","type":"true_false","statement":"Pequenas despesas diárias, como um café de 1 €, não têm impacto no orçamento.","explanation":"1 € por dia são cerca de 365 € por ano."},{"id":"steps","type":"order","prompt":"Ordena os passos para criar um orçamento:","explanation":"Primeiro medir, depois decidir.","items":["Registar o que gastas durante um mês","Separar por categorias","Comparar com o rendimento","Definir limites para o mês seguinte"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'tracking-expenses';
