insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('what-is-a-bank', 1, '{"how-banks-earn":0,"deposit-guarantee":true,"current-account":0,"liquidity-order":[0,1,2,3]}'::jsonb, 5, 4, '9127c72147f8cad35f83e9f39086acb32ba9948ebef27e99a16716647a4b7ff8')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('what-is-a-bank', 1, 'en', 'How Banks Work', 'Deposits, loans and why your money is safe', '[{"id":"intro","type":"info","title":"Banks put money to work","body":"Banks keep your money safe and make it useful. They take deposits from savers, lend part of that money to people and companies, and earn the difference between the interest they charge on loans and the interest they pay on deposits."},{"id":"how-banks-earn","type":"multiple_choice","prompt":"What is the main way a bank makes money?","explanation":"This difference is called the interest margin, and it is a bank''s core business.","options":["Charging more interest on loans than it pays on deposits","Printing new money","Selling customers'' personal data","Investing only in gold"]},{"id":"deposit-guarantee","type":"true_false","statement":"In the EU, deposits up to €100,000 per person per bank are protected if the bank fails.","explanation":"Every EU country has a deposit guarantee scheme covering up to €100,000 per depositor per bank."},{"id":"current-account","type":"fill_blank","sentence":"A ___ account is for everyday spending, while a savings account is for money you want to set aside.","explanation":"Current accounts give instant access to your money for payments and cards.","options":["current","mortgage","pension"]},{"id":"liquidity-order","type":"order","prompt":"Order from the easiest to use right away to the hardest (most liquid to least liquid):","explanation":"Liquidity is how quickly something can be turned into cash without losing value.","items":["Cash in your wallet","Money in a current account","A 12-month term deposit","A house"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('what-is-a-bank', 1, 'pt', 'Como Funcionam os Bancos', 'Depósitos, empréstimos e porque é que o teu dinheiro está seguro', '[{"id":"intro","type":"info","title":"Os bancos põem o dinheiro a trabalhar","body":"Os bancos guardam o teu dinheiro e tornam-no útil. Recebem depósitos de quem poupa, emprestam parte desse dinheiro a pessoas e empresas e ganham a diferença entre os juros que cobram nos empréstimos e os juros que pagam nos depósitos."},{"id":"how-banks-earn","type":"multiple_choice","prompt":"Qual é a principal forma de um banco ganhar dinheiro?","explanation":"Esta diferença chama-se margem financeira e é o negócio principal de um banco.","options":["Cobrar mais juros nos empréstimos do que paga nos depósitos","Imprimir dinheiro novo","Vender dados pessoais dos clientes","Investir apenas em ouro"]},{"id":"deposit-guarantee","type":"true_false","statement":"Na UE, os depósitos até 100 000 € por pessoa e por banco estão protegidos se o banco falir.","explanation":"Todos os países da UE têm um fundo de garantia de depósitos que cobre até 100 000 € por depositante e por banco."},{"id":"current-account","type":"fill_blank","sentence":"Uma conta ___ serve para o dia a dia, enquanto uma conta poupança serve para guardar dinheiro.","explanation":"As contas à ordem dão acesso imediato ao dinheiro para pagamentos e cartões.","options":["à ordem","crédito habitação","reforma"]},{"id":"liquidity-order","type":"order","prompt":"Ordena do mais fácil de usar de imediato ao mais difícil (mais líquido para menos líquido):","explanation":"Liquidez é a rapidez com que algo pode ser convertido em dinheiro sem perder valor.","items":["Dinheiro na carteira","Dinheiro na conta à ordem","Um depósito a prazo de 12 meses","Uma casa"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'what-is-a-bank';
