insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('diversification', 1, '{"most-diversified":0,"not-all-risk":false,"sectors":0,"one-bankruptcy":0}'::jsonb, 5, 4, 'a9cf9ff5a1483989848895dceb99a1f06fe7017fc9ddc9aab41e7cc28c737b42')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('diversification', 1, 'en', 'Diversification', 'Don''t put all your eggs in one basket', '[{"id":"intro","type":"info","title":"Spread your risk","body":"Diversification means spreading your money across different companies, sectors, countries and asset types, so that one bad investment doesn''t sink your whole portfolio."},{"id":"most-diversified","type":"multiple_choice","prompt":"Which portfolio is the most diversified?","explanation":"Thousands of companies across many countries and sectors is broad diversification.","options":["A global index fund with thousands of companies","All your money in one tech company","Three tech companies","Only your employer''s shares"]},{"id":"not-all-risk","type":"true_false","statement":"Diversification removes all risk from investing.","explanation":"It reduces the risk of any single company, but the whole market can still fall."},{"id":"sectors","type":"fill_blank","sentence":"Owning companies from different ___, like tech, healthcare and energy, is one way to diversify.","explanation":"Sectors react differently to the same events.","options":["sectors","passwords","logos"]},{"id":"one-bankruptcy","type":"multiple_choice","prompt":"In an equal-weight portfolio of 100 companies, one goes bankrupt. What happens?","explanation":"Each company is only 1% of the portfolio, so the damage is limited.","options":["The portfolio loses about 1% of its value","The portfolio loses everything","Nothing can ever happen","All the other companies go bankrupt too"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('diversification', 1, 'pt', 'Diversificação', 'Não ponhas os ovos todos no mesmo cesto', '[{"id":"intro","type":"info","title":"Distribui o teu risco","body":"Diversificar significa distribuir o dinheiro por diferentes empresas, setores, países e tipos de ativos, para que um mau investimento não afunde a carteira inteira."},{"id":"most-diversified","type":"multiple_choice","prompt":"Qual destas carteiras é a mais diversificada?","explanation":"Milhares de empresas em vários países e setores é uma diversificação ampla.","options":["Um fundo de índice global com milhares de empresas","Todo o dinheiro numa empresa de tecnologia","Três empresas de tecnologia","Apenas ações da empresa onde trabalhas"]},{"id":"not-all-risk","type":"true_false","statement":"A diversificação elimina todo o risco de investir.","explanation":"Reduz o risco de cada empresa individual, mas o mercado inteiro pode cair na mesma."},{"id":"sectors","type":"fill_blank","sentence":"Ter empresas de diferentes ___, como tecnologia, saúde e energia, é uma forma de diversificar.","explanation":"Os setores reagem de forma diferente aos mesmos acontecimentos.","options":["setores","palavras-passe","logótipos"]},{"id":"one-bankruptcy","type":"multiple_choice","prompt":"Numa carteira com 100 empresas em partes iguais, uma vai à falência. O que acontece?","explanation":"Cada empresa é só 1% da carteira, por isso o impacto é limitado.","options":["A carteira perde cerca de 1% do valor","A carteira perde tudo","Nunca pode acontecer nada","Todas as outras empresas também vão à falência"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'diversification';
