  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('risk-vs-reward', 1, 'en', 'Risk vs. Reward', 'Understanding investment trade-offs', '[{"id":"intro","type":"info","title":"There is no free lunch","body":"Every investment has a trade-off. The chance of higher returns usually comes with higher risk: the possibility that its value falls, sometimes a lot, especially in the short term."},{"id":"lowest-risk","type":"multiple_choice","prompt":"Which of these is usually the lowest-risk option?","explanation":"Guaranteed deposits have low risk, but also low returns.","options":["A guaranteed savings deposit","Shares of a single new startup","Cryptocurrency","Options trading"]},{"id":"no-guarantee","type":"true_false","statement":"A higher potential return means a guaranteed higher return.","explanation":"Potential is not a promise. Riskier investments can also lose money."},{"id":"volatility","type":"fill_blank","sentence":"Volatility measures how much an investment''s price ___ over time.","explanation":"High volatility means bigger and more frequent price swings.","options":["moves up and down","is guaranteed","is taxed"]},{"id":"time-horizon","type":"multiple_choice","prompt":"Why can a young investor often take more risk than someone about to retire?","explanation":"Your time horizon, how long until you need the money, shapes how much risk you can take.","options":["They have more time to recover from market drops","They pay no taxes","Stocks are cheaper for young people","Risk does not exist for young people"]},{"id":"risk-ladder","type":"order","prompt":"Order from typically lowest to highest risk:","explanation":"The less diversified and the more dependent on one outcome, the higher the risk.","items":["Savings deposit","Government bonds","Diversified stock index fund","Shares of a single small company"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('risk-vs-reward', 1, 'pt', 'Risco vs. Retorno', 'Perceber os compromissos de cada investimento', '[{"id":"intro","type":"info","title":"Não há almoços grátis","body":"Todos os investimentos implicam um compromisso. A possibilidade de retornos mais altos vem normalmente com mais risco: a hipótese de o valor cair, por vezes muito, sobretudo no curto prazo."},{"id":"lowest-risk","type":"multiple_choice","prompt":"Qual destas é normalmente a opção de menor risco?","explanation":"Os depósitos garantidos têm baixo risco, mas também baixo retorno.","options":["Um depósito de poupança garantido","Ações de uma única startup","Criptomoedas","Negociação de opções"]},{"id":"no-guarantee","type":"true_false","statement":"Um retorno potencial mais alto significa um retorno garantido mais alto.","explanation":"Potencial não é uma promessa. Os investimentos mais arriscados também podem perder dinheiro."},{"id":"volatility","type":"fill_blank","sentence":"A volatilidade mede o quanto o preço de um investimento ___ ao longo do tempo.","explanation":"Volatilidade alta significa oscilações de preço maiores e mais frequentes.","options":["sobe e desce","está garantido","é tributado"]},{"id":"time-horizon","type":"multiple_choice","prompt":"Porque é que um investidor jovem pode muitas vezes correr mais risco do que alguém prestes a reformar-se?","explanation":"O teu horizonte temporal, ou seja, quanto tempo falta até precisares do dinheiro, define quanto risco podes correr.","options":["Tem mais tempo para recuperar de quedas do mercado","Não paga impostos","As ações são mais baratas para jovens","O risco não existe para os jovens"]},{"id":"risk-ladder","type":"order","prompt":"Ordena do risco normalmente mais baixo para o mais alto:","explanation":"Quanto menos diversificado e mais dependente de um único resultado, maior o risco.","items":["Depósito de poupança","Obrigações do Estado","Fundo de índice de ações diversificado","Ações de uma única pequena empresa"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'risk-vs-reward';
