insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('types-of-investments', 1, 'en', 'Types of Investments', 'Stocks, bonds, ETFs and more', '[{"id":"intro","type":"info","title":"The main asset types","body":"Stocks are a share of ownership in a company. Bonds are loans to a government or company that pay you interest. Funds and ETFs are baskets holding many investments at once. Cash and deposits are the safest, but grow the least."},{"id":"share-owner","type":"multiple_choice","prompt":"When you buy a share of a company, you become…","explanation":"Shareholders own a small piece of the company and share in its success or failure.","options":["A part-owner of the company","A lender to the company","An employee","The company''s bank"]},{"id":"bond","type":"multiple_choice","prompt":"What is a bond?","explanation":"Bondholders are lenders: they receive interest (the coupon) and get their money back at maturity.","options":["A loan you make to a government or company in exchange for interest","A share of ownership in a company","A type of current account","A cryptocurrency"]},{"id":"etf-basket","type":"true_false","statement":"An ETF lets you buy many different investments in a single purchase.","explanation":"One ETF can hold hundreds or thousands of companies."},{"id":"dividends","type":"fill_blank","sentence":"Companies may share part of their profits with shareholders through ___.","explanation":"Dividends are cash payments to shareholders. Not every company pays them.","options":["dividends","mortgages","deposits"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('types-of-investments', 1, 'pt', 'Tipos de Investimentos', 'Ações, obrigações, ETFs e mais', '[{"id":"intro","type":"info","title":"Os principais tipos de ativos","body":"As ações são uma parte da propriedade de uma empresa. As obrigações são empréstimos a um Estado ou empresa que te pagam juros. Os fundos e ETFs são cabazes com muitos investimentos de uma vez. O dinheiro e os depósitos são os mais seguros, mas os que menos crescem."},{"id":"share-owner","type":"multiple_choice","prompt":"Quando compras uma ação de uma empresa, tornas-te…","explanation":"Os acionistas são donos de uma pequena parte da empresa e participam no seu sucesso ou fracasso.","options":["Coproprietário da empresa","Credor da empresa","Funcionário","O banco da empresa"]},{"id":"bond","type":"multiple_choice","prompt":"O que é uma obrigação?","explanation":"Os obrigacionistas são credores: recebem juros (o cupão) e o dinheiro de volta na maturidade.","options":["Um empréstimo que fazes a um Estado ou empresa em troca de juros","Uma parte da propriedade de uma empresa","Um tipo de conta à ordem","Uma criptomoeda"]},{"id":"etf-basket","type":"true_false","statement":"Um ETF permite-te comprar muitos investimentos diferentes numa só compra.","explanation":"Um só ETF pode conter centenas ou milhares de empresas."},{"id":"dividends","type":"fill_blank","sentence":"As empresas podem partilhar parte dos lucros com os acionistas através de ___.","explanation":"Os dividendos são pagamentos em dinheiro aos acionistas. Nem todas as empresas os pagam.","options":["dividendos","hipotecas","depósitos"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'types-of-investments';
