insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('what-is-a-stock', 1, '{"ticker":0,"prices-move":false,"market-cap":0,"exchange":0,"buying-steps":[0,1,2,3]}'::jsonb, 6, 5, 'dce8acc9b5234a3f5a4389fbb8f89278d0507daef8e7a9fc5b14c93d89c2ff76')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('what-is-a-stock', 1, 'en', 'How the Stock Market Works', 'Prices, tickers and exchanges', '[{"id":"intro","type":"info","title":"A marketplace for companies","body":"A stock exchange, like Nasdaq, NYSE or Euronext, is where shares are bought and sold. A share''s price is what buyers and sellers agree it is worth right now, and it moves with company results, news, interest rates and expectations."},{"id":"ticker","type":"multiple_choice","prompt":"What is \"AAPL\"?","explanation":"Tickers are short codes that identify each listed company.","options":["Apple''s ticker symbol on the stock exchange","Apple''s bank account number","A type of bond","A stock exchange"]},{"id":"prices-move","type":"true_false","statement":"Stock prices only change once a year, when companies publish results.","explanation":"Prices change every second while the market is open."},{"id":"market-cap","type":"fill_blank","sentence":"Market capitalisation = share price × number of ___.","explanation":"Market cap is what the market says the whole company is worth.","options":["shares outstanding","employees","stores"]},{"id":"exchange","type":"multiple_choice","prompt":"Which of these is a stock exchange?","explanation":"Euronext runs exchanges in Lisbon, Paris, Amsterdam, Milan and other cities.","options":["Euronext","Visa","Spotify","Eurostat"]},{"id":"buying-steps","type":"order","prompt":"Order the steps of buying a share:","explanation":"Try it now in the Explore tab with your virtual money!","items":["Research the company","Decide how much to invest","Place a buy order","Follow the investment over time"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('what-is-a-stock', 1, 'pt', 'Como Funciona a Bolsa', 'Preços, tickers e bolsas de valores', '[{"id":"intro","type":"info","title":"Um mercado de empresas","body":"Uma bolsa de valores, como a Nasdaq, a NYSE ou a Euronext, é onde se compram e vendem ações. O preço de uma ação é o que compradores e vendedores acordam que vale neste momento, e muda com os resultados da empresa, notícias, taxas de juro e expectativas."},{"id":"ticker","type":"multiple_choice","prompt":"O que é \"AAPL\"?","explanation":"Os tickers são códigos curtos que identificam cada empresa cotada.","options":["O símbolo (ticker) da Apple na bolsa","O número da conta bancária da Apple","Um tipo de obrigação","Uma bolsa de valores"]},{"id":"prices-move","type":"true_false","statement":"Os preços das ações só mudam uma vez por ano, quando as empresas publicam resultados.","explanation":"Os preços mudam a cada segundo enquanto o mercado está aberto."},{"id":"market-cap","type":"fill_blank","sentence":"Capitalização bolsista = preço da ação × número de ___.","explanation":"A capitalização bolsista é quanto o mercado diz que a empresa inteira vale.","options":["ações emitidas","funcionários","lojas"]},{"id":"exchange","type":"multiple_choice","prompt":"Qual destas é uma bolsa de valores?","explanation":"A Euronext gere as bolsas de Lisboa, Paris, Amesterdão, Milão e outras cidades.","options":["Euronext","Visa","Spotify","Eurostat"]},{"id":"buying-steps","type":"order","prompt":"Ordena os passos para comprar uma ação:","explanation":"Experimenta agora no separador Explorar com o teu dinheiro virtual!","items":["Pesquisar a empresa","Decidir quanto investir","Colocar uma ordem de compra","Acompanhar o investimento ao longo do tempo"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'what-is-a-stock';
