insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('guaranteed-returns', 1, '{"twenty":false,"friend":0,"past":0,"concepts":[0,1,2],"loss":1500}'::jsonb, 6, 5, '312f3f9251bc16ae9f8c6334d1808517625652ee5ba9323d3d81cb467e47b0a5')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('guaranteed-returns', 1, 'en', 'Guaranteed Returns', 'High returns without risk do not exist', '[{"id":"intro","type":"info","title":"Return comes with risk","body":"In investing, higher expected returns come with more risk. If someone promises high, guaranteed gains with no risk, it is probably a scam. Even serious products always show their risks and warn that past returns do not guarantee future ones."},{"id":"twenty","type":"true_false","statement":"A legitimate investment can guarantee 20% a year with no risk at all.","explanation":"Guaranteed products pay much less; high returns always carry risk."},{"id":"friend","type":"multiple_choice","prompt":"A friend says it is \"impossible to lose\" with a new investment. What do you do?","explanation":"Checking takes minutes; losing savings can take years to recover.","options":["Ask for written information and check the entity","Invest now so you don''t miss out","Take a loan to invest more","Share it with the whole family"]},{"id":"past","type":"fill_blank","sentence":"___ returns do not guarantee future returns.","explanation":"This warning appears on every legitimate investment document.","options":["Past","Written","Promised"]},{"id":"concepts","type":"match","prompt":"Match each term to its meaning","explanation":"A good offer explains all three, not just the return.","left":["Return","Risk","Liquidity"],"right":["What you may gain","The possibility of losing","How easily you get your money back"]},{"id":"loss","type":"numeric","prompt":"You invest €2,000 and lose 25%. How much do you have left (in €)?","explanation":"€2,000 − 25% = €1,500. Only invest money you can afford to see fall.","unit":"€","decimals":0}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('guaranteed-returns', 1, 'pt', 'Rentabilidades Garantidas', 'Retorno alto sem risco não existe', '[{"id":"intro","type":"info","title":"Retorno vem com risco","body":"Em investimento, um retorno esperado mais alto vem com mais risco. Se alguém promete ganhos altos e garantidos, sem risco, provavelmente é burla. Mesmo os produtos sérios mostram sempre os riscos e avisam que rentabilidades passadas não garantem rentabilidades futuras."},{"id":"twenty","type":"true_false","statement":"Um investimento legítimo pode garantir 20% ao ano sem qualquer risco.","explanation":"Os produtos garantidos rendem muito menos; retornos altos têm sempre risco."},{"id":"friend","type":"multiple_choice","prompt":"Um amigo diz que é \"impossível perder\" com um investimento novo. O que fazes?","explanation":"Verificar demora minutos; recuperar poupanças perdidas pode demorar anos.","options":["Pedir informação escrita e verificar a entidade","Investir já para não perder a oportunidade","Pedir um empréstimo para investir mais","Partilhar com toda a família"]},{"id":"past","type":"fill_blank","sentence":"Rentabilidades ___ não garantem rentabilidades futuras.","explanation":"Este aviso aparece em todos os documentos de investimento legítimos.","options":["passadas","escritas","prometidas"]},{"id":"concepts","type":"match","prompt":"Liga cada termo ao seu significado","explanation":"Uma boa oferta explica os três, não só o retorno.","left":["Retorno","Risco","Liquidez"],"right":["O que podes ganhar","A possibilidade de perder","A facilidade de recuperar o dinheiro"]},{"id":"loss","type":"numeric","prompt":"Investes 2000 € e perdes 25%. Com quanto ficas (em €)?","explanation":"2000 € − 25% = 1500 €. Investe só dinheiro que aguentas ver descer.","unit":"€","decimals":0}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'guaranteed-returns';
