insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('ponzi-schemes', 1, '{"source":0,"lasts":true,"red-flag":0,"recruit":0,"promise":100}'::jsonb, 6, 5, 'f1f0049b5e12f4c03f736ccd2dd094831ee666d016aab13bf8cffc8addffebd5')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('ponzi-schemes', 1, 'en', 'Ponzi Schemes', 'When "profits" are other people''s money', '[{"id":"intro","type":"info","title":"Paying old investors with new money","body":"In a Ponzi scheme, the \"profits\" paid to early investors come from the money of new investors, not from a real business. It works while new money keeps coming in; when it stops, it collapses and most people lose everything."},{"id":"source","type":"multiple_choice","prompt":"Where do the payments in a Ponzi scheme come from?","explanation":"There is no real activity generating returns.","options":["From new investors'' money","From a company''s profits","From central bank interest","From taxes"]},{"id":"lasts","type":"true_false","statement":"A Ponzi scheme can pay returns for months or years before collapsing.","explanation":"Early payments build trust, which is exactly how it attracts more victims."},{"id":"red-flag","type":"multiple_choice","prompt":"Which of these is a red flag?","explanation":"High, steady, risk-free returns do not exist in legitimate investing.","options":["A promise of 5% a month with no risk","A document listing costs and risks","An entity registered with the regulator","A clear explanation of where returns come from"]},{"id":"recruit","type":"fill_blank","sentence":"If you are asked to ___ new people to earn more, be suspicious: it may be a pyramid scheme.","explanation":"When income depends on recruiting, the scheme needs endless new members.","options":["recruit","ignore","inform"]},{"id":"promise","type":"numeric","prompt":"An offer promises 10% a month. How much would €1,000 \"earn\" in one month according to the promise (in €)?","explanation":"€100 a month would be over 200% a year: a classic sign of a scam.","unit":"€","decimals":0}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('ponzi-schemes', 1, 'pt', 'Esquemas Ponzi', 'Quando os "lucros" são o dinheiro dos outros', '[{"id":"intro","type":"info","title":"Pagar antigos com dinheiro de novos","body":"Num esquema Ponzi, os \"lucros\" pagos aos primeiros investidores vêm do dinheiro dos novos, não de um negócio real. Funciona enquanto entra dinheiro novo; quando deixa de entrar, colapsa e a maioria perde tudo."},{"id":"source","type":"multiple_choice","prompt":"De onde vêm os pagamentos num esquema Ponzi?","explanation":"Não há nenhuma atividade real a gerar rendimento.","options":["Do dinheiro de novos investidores","Dos lucros de uma empresa","Dos juros do banco central","Dos impostos"]},{"id":"lasts","type":"true_false","statement":"Um esquema Ponzi pode pagar rendimentos durante meses ou anos antes de colapsar.","explanation":"Os primeiros pagamentos criam confiança, e é assim que atrai mais vítimas."},{"id":"red-flag","type":"multiple_choice","prompt":"Qual destes é um sinal de alerta?","explanation":"Retornos altos, constantes e sem risco não existem em investimentos legítimos.","options":["Promessa de 5% por mês sem risco","Um documento com custos e riscos","Uma entidade registada no regulador","Uma explicação clara de onde vem o retorno"]},{"id":"recruit","type":"fill_blank","sentence":"Se te pedem para ___ novas pessoas para ganhares mais, desconfia: pode ser um esquema em pirâmide.","explanation":"Quando o ganho depende de recrutar, o esquema precisa de novos membros sem fim.","options":["recrutar","ignorar","informar"]},{"id":"promise","type":"numeric","prompt":"Uma oferta promete 10% por mês. Quanto \"renderiam\" 1000 € num mês segundo a promessa (em €)?","explanation":"100 € por mês seria mais de 200% ao ano: um sinal clássico de burla.","unit":"€","decimals":0}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'ponzi-schemes';
