insert into public.lesson_versions (lesson_id, version, answer_key, exercise_count, gradable_count, content_hash) values ('gross-vs-net', 1, '{"net":0,"payslip":[0,1,2,3],"ss":132,"same-gross":true,"payslip-name":0}'::jsonb, 6, 5, '410720ea8d8096fc84905cb2c98632a2d30ed17a06949965e54e8e8ea4fee2ca')
  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('gross-vs-net', 1, 'en', 'Gross vs Net Salary', 'From your contract to your account', '[{"id":"intro","type":"info","title":"Two numbers on your payslip","body":"Gross salary is the amount in your contract. Net salary is what reaches your account after deductions: the Social Security contribution and the income tax (IRS) withheld at source. Your payslip shows each of these lines."},{"id":"net","type":"multiple_choice","prompt":"What is net salary?","explanation":"Net is what you can actually spend and save.","options":["What you receive after deductions","The amount written in the contract","Your yearly salary","The amount before taxes"]},{"id":"payslip","type":"match","prompt":"Match each payslip line to its meaning","explanation":"Reading your payslip helps you spot mistakes.","left":["Gross salary","Net salary","Social Security","Withholding tax"],"right":["Amount before deductions","Amount paid into your account","Contribution for pensions and social protection","Monthly advance on income tax"]},{"id":"ss","type":"numeric","prompt":"Your gross salary is €1,200 and you contribute 11% to Social Security. How much is that deduction (in €)?","explanation":"11% of €1,200 = €132.","unit":"€","decimals":0},{"id":"same-gross","type":"true_false","statement":"Two colleagues with the same gross salary can take home different net amounts.","explanation":"IRS withholding depends on your situation, for example dependants or marital status."},{"id":"payslip-name","type":"fill_blank","sentence":"The document showing gross pay, deductions and net pay is called a ___.","explanation":"Your employer must give you one every month.","options":["payslip","receipt","invoice"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('gross-vs-net', 1, 'pt', 'Salário Bruto vs Líquido', 'Do contrato à tua conta', '[{"id":"intro","type":"info","title":"Dois números no recibo","body":"O salário bruto é o valor do contrato. O líquido é o que chega à tua conta depois dos descontos: a contribuição para a Segurança Social e a retenção na fonte de IRS. O recibo de vencimento mostra cada uma destas parcelas."},{"id":"net","type":"multiple_choice","prompt":"O que é o salário líquido?","explanation":"O líquido é o que podes realmente gastar e poupar.","options":["O que recebes depois dos descontos","O valor escrito no contrato","O salário anual","O valor antes dos impostos"]},{"id":"payslip","type":"match","prompt":"Liga cada linha do recibo ao seu significado","explanation":"Ler o recibo ajuda-te a detetar erros.","left":["Salário bruto","Salário líquido","Segurança Social","Retenção na fonte"],"right":["Valor antes dos descontos","Valor que chega à conta","Contribuição para pensões e proteção social","Adiantamento mensal do IRS"]},{"id":"ss","type":"numeric","prompt":"O teu salário bruto é 1200 € e descontas 11% para a Segurança Social. Quanto é esse desconto (em €)?","explanation":"11% de 1200 € = 132 €.","unit":"€","decimals":0},{"id":"same-gross","type":"true_false","statement":"Dois colegas com o mesmo salário bruto podem receber líquidos diferentes.","explanation":"A retenção de IRS depende da situação de cada um, por exemplo dependentes ou estado civil."},{"id":"payslip-name","type":"fill_blank","sentence":"O documento que mostra o bruto, os descontos e o líquido chama-se recibo de ___.","explanation":"A entidade empregadora tem de to entregar todos os meses.","options":["vencimento","multibanco","compra"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'gross-vs-net';
