  on conflict (lesson_id, version) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('social-security', 1, 'en', 'Social Security Contributions', 'What you pay and what it protects', '[{"id":"intro","type":"info","title":"11% + 23.75%","body":"Employees in Portugal generally contribute 11% of their gross salary to Social Security, and the employer pays a further 23.75%. These contributions fund pensions and benefits such as sickness, parental leave and unemployment."},{"id":"rate","type":"fill_blank","sentence":"Employees generally contribute ___ of their gross salary to Social Security.","explanation":"23.75% is the general rate paid by the employer, on top of your salary.","options":["11%","23.75%","50%"]},{"id":"employer","type":"numeric","prompt":"With a gross salary of €1,000, how much does the employer generally pay to Social Security (in €)?","explanation":"23.75% of €1,000 = €237.50.","unit":"€","decimals":2},{"id":"benefit","type":"multiple_choice","prompt":"Which of these is funded by Social Security?","explanation":"Tax refunds come from the tax authority, not from Social Security.","options":["Unemployment benefit","Income tax refund","Interest on deposits","Dividends"]},{"id":"career","type":"true_false","statement":"Your contributions build your contribution record and affect your future pension.","explanation":"Years and amounts contributed are used to calculate the pension."},{"id":"who-pays","type":"match","prompt":"Match each term to its meaning","explanation":"Rates can differ in special cases; check the official Social Security website.","left":["Employee","Employer","Contribution record"],"right":["11% of gross salary (general rate)","23.75% of gross salary (general rate)","Your history of contributions over the years"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
insert into public.lesson_translations (lesson_id, version, locale, title, description, exercises) values ('social-security', 1, 'pt', 'Descontos para a Segurança Social', 'O que pagas e o que te protege', '[{"id":"intro","type":"info","title":"11% + 23,75%","body":"Quem trabalha por conta de outrem em Portugal desconta, em regra, 11% do salário bruto para a Segurança Social, e a entidade empregadora paga mais 23,75%. Estas contribuições financiam pensões e prestações como doença, parentalidade e desemprego."},{"id":"rate","type":"fill_blank","sentence":"Em regra, o trabalhador por conta de outrem desconta ___ do salário bruto para a Segurança Social.","explanation":"23,75% é a taxa geral paga pela entidade empregadora, além do teu salário.","options":["11%","23,75%","50%"]},{"id":"employer","type":"numeric","prompt":"Com um salário bruto de 1000 €, quanto paga em regra a entidade empregadora à Segurança Social (em €)?","explanation":"23,75% de 1000 € = 237,50 €.","unit":"€","decimals":2},{"id":"benefit","type":"multiple_choice","prompt":"Qual destas prestações é financiada pela Segurança Social?","explanation":"Os reembolsos de IRS vêm das Finanças, não da Segurança Social.","options":["Subsídio de desemprego","Reembolso de IRS","Juros de depósitos","Dividendos"]},{"id":"career","type":"true_false","statement":"As contribuições contam para a carreira contributiva e influenciam a futura pensão.","explanation":"Os anos e os valores descontados entram no cálculo da pensão."},{"id":"who-pays","type":"match","prompt":"Liga cada termo ao seu significado","explanation":"As taxas podem ser diferentes em casos especiais; confirma no site oficial da Segurança Social.","left":["Trabalhador","Entidade empregadora","Carreira contributiva"],"right":["11% do salário bruto (regra geral)","23,75% do salário bruto (regra geral)","O historial de descontos ao longo dos anos"]}]'::jsonb)
  on conflict (lesson_id, version, locale) do nothing;
update public.lessons set published_version = 1 where id = 'social-security';
update public.lessons set published_version = null where id not in ('dollar-cost-averaging', 'etfs-and-index-funds', 'fees-matter', 'budget-50-30-20', 'compound-interest', 'debit-vs-credit-cards', 'emergency-fund', 'inflation', 'needs-vs-wants', 'pay-yourself-first', 'phishing', 'real-interest-rate', 'saving-goals', 'tracking-expenses', 'what-is-a-bank', 'diversification', 'risk-vs-reward', 'types-of-investments', 'what-is-a-stock', 'guaranteed-returns', 'ponzi-schemes', 'gross-vs-net', 'social-security');

